import{_ as p,a0 as l,w as i,s as r,ao as t,I as e,x as a,a1 as n,A as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const A=JSON.parse('{"title":"怎樣在 Android 上手動備份你的短信/彩信？ | LCTT x X-CMD","titleTemplate":false,"description":"怎樣在 Android 上手動備份你的短信/彩信？ | LCTT (201612) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"怎樣在 Android 上手動備份你的短信/彩信？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"怎樣在 Android 上手動備份你的短信/彩信？ | LCTT (201612) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201612/20161017 How To Manually Backup Your SMS MMS Messages On Android","title":"怎樣在 Android 上手動備份你的短信/彩信？","tag":"201612","desc":""},"relativePath":"201612/20161017 How To Manually Backup Your SMS MMS Messages On Android.md","filePath":"[post].md"}'),m={name:"201612/20161017 How To Manually Backup Your SMS MMS Messages On Android.md"};function u(T,s,b,f,g,S){const o=l("Link");return i(),r("div",null,[s[17]||(s[17]=t('<h1 id="怎樣在-android-上手動備份你的短信-彩信" tabindex="-1">怎樣在 Android 上手動備份你的短信/彩信？ <a class="header-anchor" href="#怎樣在-android-上手動備份你的短信-彩信" aria-label="Permalink to “怎樣在 Android 上手動備份你的短信/彩信？”">​</a></h1><p><img src="https://iwf1.com/wordpress/wp-content/uploads/2016/10/Android-backup-sms-mms.jpg" alt="Android backup sms"></p><p>如果你要換一部手機或升級你的系統，備份你的數據就變得至關重要。我們存儲重要數據的位置之一就是我們的短信/彩信，不管是感情價值還是實用價值，備份它們是很有用的。</p><p>然而，不像照片、視頻或音頻文件可以相對容易地傳輸和備份，備份短信/彩信比較複雜，通常需要使用第三方 app 或服務。</p><h3 id="為什麼要手動備份" tabindex="-1">為什麼要手動備份 <a class="header-anchor" href="#為什麼要手動備份" aria-label="Permalink to “為什麼要手動備份”">​</a></h3><p>儘管現在有很多不同的 app 能夠幫你備份短信/彩信，你可能因為以下原因，考慮自己動手備份它們：</p><ol><li>app <strong>可能不能</strong>在所有的設備和安卓版本上都工作。</li><li>app 可能把你的備份數據上傳到雲端， 有<strong>破壞你的內容安全</strong>的風險。</li><li>通過手動備份，你可以完全掌握你的數據通過哪裏，走向哪裏，備份過程中減少被間諜軟件窺視的危險。</li><li>手動備份相比其他方法<strong>更省時，更省力，更直接</strong>。</li></ol><h3 id="怎麼手動備份短信-彩信" tabindex="-1">怎麼手動備份短信/彩信？ <a class="header-anchor" href="#怎麼手動備份短信-彩信" aria-label="Permalink to “怎麼手動備份短信/彩信？”">​</a></h3>',8)),e("p",null,[s[1]||(s[1]=a("要手動備份你的短信/彩信，你需要在你的電腦上安裝一個叫做  ",-1)),n(o,{href:"http://developer.android.com/tools/help/adb.html"},{default:d(()=>[...s[0]||(s[0]=[a("adb",-1)])]),_:1}),s[2]||(s[2]=a(" 的安卓工具。",-1))]),s[18]||(s[18]=t(`<p>現在，需要重點知道的是，安卓把短信/彩信通常存儲在一個叫做 <code>mmssms.db</code> 的資料庫裏。</p><p>因為在不同設備上這個資料庫的位置可能不相同，而且，其他短信 app 會創建它們自己的資料庫，比如 GO SMS 會創建 <code>gommssms.db</code> 資料庫， 所以你需要做的第一件事是搜索這些資料庫。</p><p>打開命令列工具（我使用了 Linux Terminal， 你也可以使用 Windows CMD 或 PowerShell ）並運行以下命令：</p><p>注意： 以下是完成該任務的一系列命令，再後面是每個命令用途的解釋。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>adb root</span></span>
<span class="line"><span>adb shell</span></span>
<span class="line"><span>find / -name &quot;*mmssms*&quot;</span></span>
<span class="line"><span>exit</span></span>
<span class="line"><span></span></span>
<span class="line"><span>adb pull /PATH/TO/mmssms.db /PATH/TO/DESTINATION/FOLDER</span></span></code></pre></div><h4 id="解釋" tabindex="-1">解釋 <a class="header-anchor" href="#解釋" aria-label="Permalink to “解釋”">​</a></h4><p>一開始我們使用 <code>adb root</code> 命令來以 root 模式啓動 adb － 這樣我們就有了讀取系統保護文件的權限。</p><p><code>adb shell</code> 用來進入設備的 shell。</p><p>然後， <code>find</code> 命令用來搜索資料庫。（在我的例子中，我發現數據庫在 <code>/data/data/com.android.providers.telephony/databases/mmssms.db</code>)</p><p>建議：如果你的終端輸出了太多無關的結果，可以試試使用 <code>find</code> 的參數來精簡結果。(具體參數可以搜索引擎查下)</p>`,10)),e("p",null,[n(o,{href:"http://iwf1.com/wordpress/wp-content/uploads/2016/10/Android-SMSMMS-databases.jpg"},{default:d(()=>[...s[3]||(s[3]=[e("img",{src:"http://iwf1.com/wordpress/wp-content/uploads/2016/10/Android-SMSMMS-databases-730x726.jpg",alt:"Android SMS&MMS databases"},null,-1)])]),_:1})]),s[19]||(s[19]=t("<p><em>安卓短信/彩信資料庫</em></p><p>然後我們使用 <code>exit</code> 命令回退到我們的本地系統目錄。</p><p>最後，使用 <code>adb pull</code> 把資料庫文件複製到我們電腦的一個文件夾裏。</p><p>現在，當你想要還原短信/彩信時，不管是還原到新的設備還是新的系統版本， 只要再次搜索新系統中短信/彩信的具體位置，並用我們備份的資料庫替換它即可。</p><p>使用 <code>adb push</code> 來替換它，例如：<code>adb push ~/Downloads/mmssms.db /data/data/com.android.providers.telephony/databases/mmssms.db</code></p><hr>",6)),e("p",null,[s[5]||(s[5]=a("via: ",-1)),n(o,{href:"https://iwf1.com/how-to-manually-backup-your-sms-mms-messages-on-android/"},{default:d(()=>[...s[4]||(s[4]=[a("https://iwf1.com/how-to-manually-backup-your-sms-mms-messages-on-android/",-1)])]),_:1})]),e("p",null,[s[9]||(s[9]=a("作者：",-1)),n(o,{href:"https://iwf1.com/tag/android"},{default:d(()=>[...s[6]||(s[6]=[a("Liron",-1)])]),_:1}),s[10]||(s[10]=a(" 譯者：",-1)),n(o,{href:"http://wangzk.win"},{default:d(()=>[...s[7]||(s[7]=[a("willcoderwang",-1)])]),_:1}),s[11]||(s[11]=a(" 校對：",-1)),n(o,{href:"https://github.com/jasminepeng"},{default:d(()=>[...s[8]||(s[8]=[a("jasminepeng",-1)])]),_:1})]),e("p",null,[s[14]||(s[14]=a("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:d(()=>[...s[12]||(s[12]=[a("LCTT",-1)])]),_:1}),s[15]||(s[15]=a(" 原創編譯，",-1)),n(o,{href:"https://linux.cn/"},{default:d(()=>[...s[13]||(s[13]=[a("Linux中國",-1)])]),_:1}),s[16]||(s[16]=a(" 榮譽推出",-1))])])}const _=p(m,[["render",u]]);export{A as __pageData,_ as default};
